export const FOOD_CATEGORIES = ["Bevande","Carboidrati","Grassi","Proteine","Snack","Verdure"];
export function searchFoodCatalog(query, limit = 40) {
  const q = String(query || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  const sortFn = (a, b) => String(a.category||'').localeCompare(String(b.category||''),'it') || String(a.name||'').localeCompare(String(b.name||''),'it');
  if (!q) return FOOD_CATALOG.slice().sort(sortFn).slice(0, limit);
  return FOOD_CATALOG.filter((f) => {
    const blob = [f.name, f.name_en, f.brand, f.category, ...(f.aliases||[])].filter(Boolean).join(' ').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
    if (blob.includes(q)) return true;
    return blob.split(/\s+/).some((w) => w.startsWith(q));
  }).sort(sortFn).slice(0, limit);
}
export default { FOOD_CATALOG, FOOD_CATEGORIES, searchFoodCatalog };
